$(document).ready(function(){var $doc=$(this);$doc.on('change','.lang_chooser select',function(e){window.location.href=$(this).val();});$doc.on('click','.fancybox-ordering',function(e){e.preventDefault();var $t=$(this);var href=$t.attr('href');var $modal=$(href);var $wrapper=$t.closest('.ordering_frame');var date1=$wrapper.find('.date_input1_js').val();var date2=$wrapper.find('.date_input2_js').val();var number1=$wrapper.find('.number1_js').val();var number2=$wrapper.find('.number2_js').val();$modal.find('.date1-js').val(date1);$modal.find('.date2-js').val(date2);$modal.find('.number1-js').val(number1);$modal.find('.number2-js').val(number2);$.fancybox.open($modal);});cf7Init();});document.addEventListener('wpcf7mailsent',function(event){$.fancybox.close();$.fancybox.open({src:'#myThanks',touch:false,baseClass:'thanks_msg'});setTimeout(function(){$.fancybox.close();},3000);$('.mfv_checker_ico').removeClass('active');},false);document.addEventListener('wpcf7invalid',function(event){var invalid_fields=event.detail.apiResponse.invalid_fields;for(var a=0;a<invalid_fields.length;a++){var id=invalid_fields[a].error_id;$(document).find('input[aria-describedby="'+id+'"]').addClass('error');}},false);function cf7Init(){$('.mfv_checker_input').each(function(){var $t=$(this);$t.on('change',function(){if($t.prop('checked')===true){$t.closest('.mfv_checker').find('.mfv_checker_ico').addClass('active');}else{$t.closest('.mfv_checker').find('.mfv_checker_ico').removeClass('active');}});});}